    public function sign(string $path, array $api = array('public'), string $method = 'GET', $params = array()): array {
        $apiName = $api[0];
        $baseApiUrl = $this->safe_string($this->urls['api'], $apiName);
        if ($baseApiUrl === null) {
            throw new ExchangeError($this->id . ' sign() has no API URL for ' . $apiName);
        }
        $implodePath = $this->implode_params($path, $params);
        $queryParams = $this->omit($params, $this->extract_params($path));
        $url = $baseApiUrl . '/' . $implodePath;
        if ((strtoupper($method) !== 'POST') && (count($queryParams) > 0)) {
            $url .= '?' . $this->urlencode($queryParams);
        }
        return array(
            'url' => $url,
            'method' => $method,
            'body' => null,
            'headers' => array( 'Accept' => 'application/json' ),
        );
    }

