    private function do_fetch_ticker(string $symbol, $params = array()) {
        /** fetchTicker
         * fetches information on $price, a 24-hour trading stats for a specific $market; note that the exchange exposes only the most recent 50 trades, so aggregates are computed over that window
         *
         * @see https://trade->smartcore.su/api/products/{id}/book
         *
         * @param {string} $symbol unified $symbol of the $market to fetch a $ticker for
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a $ticker structure
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $bookRequest = Async\await($this->publicGetProductsIdBook($this->extend(array( 'id' => $market['id'] ), $params)));
        $tradesResponse = Async\await($this->publicGetProductsIdTrades($this->extend(array( 'id' => $market['id'] ), $params)));
        $timestamp = $this->safe_integer($bookRequest, 'time');
        // the public API only exposes the most recent ~50 trades, with no
        // 24h stats endpoint, so OHLCV-style aggregates (open/high/low/
        // baseVolume/quoteVolume) are intentionally left undefined instead
        // of being misrepresented as 24h figures. the raw window aggregates
        // are kept under info['window'] for transparency
        $last = null;
        $lastTimestamp = null;
        $windowHigh = null;
        $windowLow = null;
        $windowBaseVolume = 0;
        $windowQuoteVolume = 0;
        for ($i = 0; $i < count($tradesResponse); $i++) {
            $trade = $tradesResponse[$i];
            $price = $this->safe_number($trade, 'price');
            $amount = $this->safe_number($trade, 'size');
            if ($price === null || $amount === null) {
                continue;
            }
            $tradeTimestamp = $this->parse8601($this->safe_string($trade, 'time'));
            if ($tradeTimestamp !== null && ($lastTimestamp === null || $tradeTimestamp >= $lastTimestamp)) {
                $lastTimestamp = $tradeTimestamp;
                $last = $price;
            }
            $windowHigh = ($windowHigh === null) ? $price : max($windowHigh, $price);
            $windowLow = ($windowLow === null) ? $price : min($windowLow, $price);
            $windowBaseVolume = $this->sum($windowBaseVolume, $amount);
            $windowQuoteVolume = $this->sum($windowQuoteVolume, $price * $amount);
        }
        $bidsArray = $this->safe_value($bookRequest, 'bids', array());
        $asksArray = $this->safe_value($bookRequest, 'asks', array());
        $bestBid = (strlen($bidsArray) > 0) ? $bidsArray[0] : null;
        $bestAsk = (strlen($asksArray) > 0) ? $asksArray[0] : null;
        $ticker = array(
            'symbol' => $market['symbol'],
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'last' => $last,
            'high' => null,
            'low' => null,
            'bid' => ($bestBid !== null) ? $this->safe_number($bestBid, 0) : null,
            'bidVolume' => ($bestBid !== null) ? $this->safe_number($bestBid, 1) : null,
            'ask' => ($bestAsk !== null) ? $this->safe_number($bestAsk, 0) : null,
            'askVolume' => ($bestAsk !== null) ? $this->safe_number($bestAsk, 1) : null,
            'vwap' => null,
            'open' => null,
            'close' => null,
            'previousClose' => null,
            'change' => null,
            'percentage' => null,
            'average' => null,
            'baseVolume' => null,
            'quoteVolume' => null,
            'lastTradeTimestamp' => $lastTimestamp,
            'info' => array( 'book' => $bookRequest, 'window' => array( 'high' => $windowHigh, 'low' => $windowLow, 'baseVolume' => $windowBaseVolume, 'quoteVolume' => $windowQuoteVolume, 'tradesCount' => strlen($tradesResponse) )),
        );
        return $this->safe_ticker($ticker, $market);
    }

    public function handle_errors(float $statusCode, string $statusText, string $url, string $method, array $responseHeaders, string $responseBody, mixed $response, mixed $requestHeaders, mixed $requestBody) {
        $message = $this->safe_string($response, 'message');
        if ($statusCode === 429) {
            $suffix = '';
            if ($message !== null) {
                $suffix = ' => ' . $message;
            }
            throw new RateLimitExceeded($this->id . ' rate limit exceeded' . $suffix);
        }
        if ($message !== null) {
            if ($statusCode >= 400 && $statusCode < 500) {
                throw new BadResponse($this->id . ' ' . $message);
            }
            // the exchange wraps most internal failures (including unknown
            // product lookups) into HTTP 500 with a { "message": ... } body
            if ($statusCode >= 500) {
                throw new ExchangeError($this->id . ' ' . $message);
            }
        }
        return null;
    }
